import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class AdminUsersScreen extends StatefulWidget{const AdminUsersScreen({super.key});@override State<AdminUsersScreen> createState()=>_AdminUsersScreenState();}
class _AdminUsersScreenState extends State<AdminUsersScreen>{bool loading=true;String? error;List<Map<String,dynamic>> users=[];String query='';@override void initState(){super.initState();_load();}Future<void>_load()async{setState(()=>loading=true);final r=await ApiService.getAdminUsers();if(!mounted)return;if(r["success"]==true){final raw=r["users"];users=raw is List?raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():[];error=null;}else error=r["message"]?.toString()??'Erro';setState(()=>loading=false);}@override Widget build(BuildContext context){final filtered=users.where((u){final q=query.toLowerCase();return q.isEmpty||u.values.any((v)=>v?.toString().toLowerCase().contains(q)==true);}).toList();return Scaffold(appBar:AppBar(title:const Text('Usuários'),actions:[IconButton(onPressed:loading?null:_load,icon:const Icon(Icons.refresh))]),backgroundColor:const Color(0xFFF5F7F6),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>query=v),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Buscar nome, e-mail ou telefone',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14),borderSide:BorderSide.none)))),Expanded(child:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):ListView.builder(padding:const EdgeInsets.all(12),itemCount:filtered.length,itemBuilder:(_,i){final u=filtered[i];final n=(u["name"]??'?').toString();return Card(elevation:0,child:ListTile(leading:CircleAvatar(child:Text(n.isEmpty?'?':n.substring(0,1).toUpperCase())),title:Text(n.isEmpty?'—':n),subtitle:Text('${u["email"]??'—'}\n${u["phone"]??'—'}'),isThreeLine:true,trailing:Chip(label:Text(u["is_driver"]==true?'Motorista':'Cliente'))));}))]));}}
